import { useState, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import '../../carrito.css'; // Reutilizamos estilos de modal y botones

export default function ProfileModal({ isOpen, onClose }) {
  const { user, updateProfile, updatePassword } = useAuth();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const fileInputRef = useRef();

  // Estados Formulario
  const [nombre, setNombre] = useState(user?.nombre || '');
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [preview, setPreview] = useState(user?.avatar ? `http://localhost:4000${user.avatar}` : null);

  if (!isOpen) return null;

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPreview(reader.result);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      const formData = new FormData();
      formData.append('nombre', nombre);
      if (fileInputRef.current.files[0]) {
        formData.append('avatar', fileInputRef.current.files[0]);
      }

      await updateProfile(formData);
      setSuccess('Perfil actualizado correctamente');
      setTimeout(() => setSuccess(null), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Error al actualizar perfil');
    } finally {
      setLoading(false);
    }
  };

  const handleSavePassword = async (e) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      return setError('Las nuevas contraseñas no coinciden');
    }

    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      await updatePassword({ currentPassword, newPassword });
      setSuccess('Contraseña cambiada con éxito');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setTimeout(() => setSuccess(null), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Error al cambiar contraseña');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="cart-modal-overlay" style={{ zIndex: 2000 }}>
      <div className="cart-modal" style={{ maxWidth: '500px', width: '90%' }}>
        <div className="cart-modal__header">
          <h3>👤 Mi Perfil</h3>
          <button className="cart-modal__close" onClick={onClose}>&times;</button>
        </div>

        <div className="cart-modal__body" style={{ maxHeight: '80vh', overflowY: 'auto' }}>
          {error && <div className="alert alert-danger mb-4">{error}</div>}
          {success && <div className="alert alert-success mb-4">{success}</div>}

          {/* Sección Avatar y Nombre */}
          <form onSubmit={handleSaveProfile} className="mb-6 pb-6 border-b border-gray-200">
            <h4 className="text-sm font-bold uppercase mb-4 text-gray-500">Información General</h4>

            <div className="flex flex-col items-center mb-4">
              <div 
                className="w-24 h-24 rounded-full bg-gray-100 mb-2 overflow-hidden border-4 border-white shadow-sm flex items-center justify-center cursor-pointer hover:opacity-80 transition-opacity"
                onClick={() => fileInputRef.current.click()}
              >
                {preview ? (
                  <img src={preview} alt="Avatar" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-4xl">📸</span>
                )}
              </div>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                style={{ display: 'none' }} 
                accept="image/*"
              />
              <span className="text-xs text-gray-400">Clic para cambiar imagen</span>
            </div>

            <div className="form-group mb-4">
              <label>Nombre Completo</label>
              <input 
                type="text" 
                className="form-control" 
                value={nombre} 
                onChange={(e) => setNombre(e.target.value)} 
                required
              />
            </div>
            <button className="btn btn-primary w-full" disabled={loading}>
              {loading ? 'Guardando...' : 'Actualizar Datos'}
            </button>
          </form>

          {/* Sección Contraseña */}
          <form onSubmit={handleSavePassword}>
            <h4 className="text-sm font-bold uppercase mb-4 text-gray-500">Seguridad</h4>

            <div className="form-group mb-3">
              <label>Contraseña Actual</label>
              <input 
                type="password" 
                className="form-control" 
                value={currentPassword} 
                onChange={(e) => setCurrentPassword(e.target.value)} 
                required
              />
            </div>

            <div className="form-group mb-3">
              <label>Nueva Contraseña</label>
              <input 
                type="password" 
                className="form-control" 
                value={newPassword} 
                onChange={(e) => setNewPassword(e.target.value)} 
                required
                minLength={6}
              />
            </div>

            <div className="form-group mb-4">
              <label>Confirmar Nueva Contraseña</label>
              <input 
                type="password" 
                className="form-control" 
                value={confirmPassword} 
                onChange={(e) => setConfirmPassword(e.target.value)} 
                required
              />
            </div>

            <button className="btn btn-outline w-full" disabled={loading}>
              {loading ? 'Procesando...' : 'Cambiar Contraseña'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
